import { Hono } from "hono";
import type { AppEnv } from "./env";
import { one } from "./one";
import { gmail } from "./one/actions.gen";

// Acme Inc contact form: a visitor who is not signed in sends a message, and
// it reaches the owner's inbox as an email sent on the owner's grant.
export const contact = new Hono<AppEnv>();

const cap = (v: unknown, n: number) => (typeof v === "string" ? v.trim().slice(0, n) : "");

contact.post("/", async (c) => {
  const b = await c.req.json<{ name?: string; email?: string; message?: string }>().catch(() => ({}) as { name?: string; email?: string; message?: string });
  const name = cap(b.name, 120);
  const email = cap(b.email, 200);
  const message = cap(b.message, 4000);
  if (!name || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) || !message) return c.json({ error: { code: "bad_input", message: "Name, a valid email and a message, please." } }, 400);
  const r = await one(c, { as: "owner" }).run(gmail.sendEmail, { body: { to: "support@acme.example", subject: `Contact form: ${name}`, body: `${message}\n\nFrom ${name} <${email}>` } });
  if (!r.ok) return c.json(r, r.status as 403);
  return c.json({ sent: true });
});

import { Hono } from "hono";
import type { AppEnv } from "./env";
import { contact } from "./contact";
import { oneRoutes } from "./one/connect";

// The app's API. Runtime-neutral Hono: server/worker.ts runs it on Workers,
// api/[[...route]].ts on Vercel. Add routes below the One routes.

const app = new Hono<AppEnv>();

app.get("/api/health", (c) => c.json({ ok: true, app: "acme-contact" }));

// Sign in with One, the grant, and /api/one/health. Do not edit.
app.route("/api/one", oneRoutes);

// App routes go here. Routes that call one(c).run start with requireUser(c).
app.route("/api/contact", contact);

app.notFound((c) => c.json({ error: { code: "not_found", message: `No route for ${c.req.path}` } }, 404));

app.onError((err, c) => {
  console.error(err);
  return c.json({ error: { code: "server_error", message: err.message } }, 500);
});

export default app;
